function render(){let sCount=citizens.students.length;let wCount=citizens.workers.length;let cCount=citizens.customers.length;let sPresent=citizens.students.filter(s=>s.attendance==='Present').length;let wPresent=citizens.workers.filter(s=>s.attendance==='Present').length;let sFees=citizens.students.reduce((a,s)=>a+s.feesPaid,0);let wSalary=citizens.workers.reduce((a,s)=>a+s.salary,0);let cSpent=citizens.customers.reduce((a,s)=>a+s.totalSpent,0);let totalCitizens=sCount+wCount+cCount;document.getElementById('stats').innerHTML='🇱🇷 WWI Citizens — Real Citizens — For 1 School — 1 Factory — 1 Shop — Today: '+new Date().toISOString().split('T')[0]+'<br>Total Citizens: '+totalCitizens+' — 1 School: '+sCount+' Students — Present: '+sPresent+' — 1 Factory: '+wCount+' Workers — Present: '+wPresent+' — 1 Shop: '+cCount+' Customers<br>School Fees Collected: \$'+sFees.toLocaleString()+' USD = L\$'+(sFees*CBL).toLocaleString()+' L\$ — Factory Salaries: \$'+wSalary.toLocaleString()+' USD = L\$'+(wSalary*CBL).toLocaleString()+' L\$ — Shop Sales: \$'+cSpent.toLocaleString()+' USD = L\$'+(cSpent*CBL).toLocaleString()+' L\$ — Total Economy: \$'+(sFees+wSalary+cSpent).toLocaleString()+' USD = L\$'+((sFees+wSalary+cSpent)*CBL).toLocaleString()+' L\$ — At CBL L\$169.50 Real Rate — No Fake Rates — For Economy — For GOV-NET — For Liberia Africa World 🌍 — For Future — With Love — 💗 — Real Citizens — Real — Then Depth Will Spread To All — ✨💯✅🛜🏭';let list=citizens[currentTab];let html='';list.slice(0,100).forEach(s=>{if(currentTab==='students'){html+='<tr><td>'+s.id+'</td><td>'+s.name+'</td><td>'+s.grade+' — '+s.school+'</td><td>'+s.phone+'</td><td>'+s.attendance+'</td><td>\$'+s.feesPaid+' / \$'+s.feesTotal+' — L\$'+(s.feesPaid*CBL).toLocaleString()+' — Score: '+s.score+'</td><td><span class='+(s.feesPaid>=s.feesTotal?'paid':'unpaid')+'>'+(s.feesPaid>=s.feesTotal?'PAID ✅':'UNPAID ❌')+'</span></td><td><button onclick=markPresent(`'+s.id+'`,`students`)>✅/❌ Attendance</button><button onclick=pay(`'+s.id+'`,`students`)>💰 Pay Fees</button></td></tr>';}else if(currentTab==='workers'){html+='<tr><td>'+s.id+'</td><td>'+s.name+'</td><td>'+s.role+' — '+s.factory+'</td><td>'+s.phone+'</td><td>'+s.attendance+'</td><td>Salary: \$'+s.salary+' USD = L\$'+(s.salary*CBL).toLocaleString()+' L\$ — Production: '+s.production+' units</td><td><span class='+(s.salaryPaid?'paid':'unpaid')+'>'+(s.salaryPaid?'PAID ✅':'UNPAID ❌')+'</span></td><td><button onclick=markPresent(`'+s.id+'`,`workers`)>✅/❌ Attendance</button><button onclick=pay(`'+s.id+'`,`workers`)>💰 Pay Salary</button></td></tr>';}else{html+='<tr><td>'+s.id+'</td><td>'+s.name+'</td><td>'+s.shop+'</td><td>'+s.phone+'</td><td>Orders: '+s.orders+' — Last: '+s.lastOrder+'</td><td>Total Spent: \$'+s.totalSpent+' USD = L\$'+(s.totalSpent*CBL).toLocaleString()+' L\$</td><td><span class=paid>Customer ✅</span></td><td><button onclick=pay(`'+s.id+'`,`customers`)>🛒 New Purchase</button></td></tr>';}});document.getElementById('citizenTable').innerHTML=html;document.getElementById('tableTitle').innerText=currentTab==='students'?'🏫 1 SCHOOL — 100 STUDENTS — REAL — FOR DUALA — FOR LIBERIA AFRICA WORLD 🌍':currentTab==='workers'?'🏭 1 FACTORY — 100 WORKERS — REAL — FOR DUALA — FOR LIBERIA AFRICA WORLD 🌍':'🛒 1 SHOP — 100 CUSTOMERS — REAL — FOR DUALA — FOR LIBERIA AFRICA WORLD 🌍';}
